    @Test
    void returning_a_loan_makes_the_book_available_and_loanable_again() throws Exception {
        String bookId = registerBook("Working Effectively with Legacy Code");
        String memberId = registerMember("최유나");
        String loanId = loanBook(bookId, memberId);

        mockMvc.perform(post("/loans/{loanId}/return", loanId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.loanId").value(loanId))
                .andExpect(jsonPath("$.returnedAt").value(LocalDate.now().toString()));

        mockMvc.perform(get("/books/{id}", bookId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("AVAILABLE"));

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(new LoanBody(bookId, registerMember("정하윤")))))
                .andExpect(status().isCreated());
    }

    @Test
    void returning_an_already_returned_loan_returns_409() throws Exception {
        String bookId = registerBook("The Pragmatic Programmer");
        String loanId = loanBook(bookId, registerMember("한도윤"));

        mockMvc.perform(post("/loans/{loanId}/return", loanId))
                .andExpect(status().isOk());

        mockMvc.perform(post("/loans/{loanId}/return", loanId))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("ALREADY_RETURNED"));

        mockMvc.perform(get("/books/{id}", bookId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("AVAILABLE"));
    }

    @Test
    void returning_an_old_loan_after_the_book_was_loaned_again_returns_409_and_keeps_new_loan() throws Exception {
        String bookId = registerBook("Release It!");
        String firstLoanId = loanBook(bookId, registerMember("오세린"));
        mockMvc.perform(post("/loans/{loanId}/return", firstLoanId))
                .andExpect(status().isOk());
        loanBook(bookId, registerMember("윤태오"));

        mockMvc.perform(post("/loans/{loanId}/return", firstLoanId))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("ALREADY_RETURNED"));

        mockMvc.perform(get("/books/{id}", bookId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("ON_LOAN"));
    }

    @Test
    void returned_loans_do_not_count_toward_the_loan_limit() throws Exception {
        String memberId = registerMember("강서연");
        String firstLoanId = loanBook(registerBook("책 A"), memberId);
        for (int i = 2; i <= 5; i++) {
            loanBook(registerBook("책 " + i), memberId);
        }

        mockMvc.perform(post("/loans/{loanId}/return", firstLoanId))
                .andExpect(status().isOk());

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(new LoanBody(registerBook("책 6"), memberId))))
                .andExpect(status().isCreated());
    }

    @Test
    void returning_unknown_loan_returns_404() throws Exception {
        mockMvc.perform(post("/loans/{loanId}/return", UUID.randomUUID()))
                .andExpect(status().isNotFound());
    }

    private String loanBook(String bookId, String memberId) throws Exception {
        String response = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(new LoanBody(bookId, memberId))))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(response).get("loanId").asText();
    }

    private String registerBook(String title) throws Exception {
        String response = mockMvc.perform(post("/books").contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(new TitleBody(title))))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(response).get("id").asText();
    }

    private String registerMember(String name) throws Exception {
        String response = mockMvc.perform(post("/members").contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(new NameBody(name))))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(response).get("memberId").asText();
    }

    record TitleBody(String title) {
    }

    record NameBody(String name) {
    }

    record LoanBody(String bookId, String memberId) {
    }
}
